   259	    /// Finds the remainder of two values. Errors if invalid.
   260	    ///
   261	    /// NB: uses the remainder, not modulo, like Postgres. This means that for
   262	    /// negative values, the result has the sign of the dividend, rather than
   263	    /// always returning a positive value.
   264	    pub fn checked_rem(&self, other: &Self) -> Result<Self> {
   265	        use Value::*;
   266	
   267	        Ok(match (self, other) {
   268	            (Integer(_), Integer(0)) => return errinput!("can't divide by zero"),
   269	            (Integer(lhs), Integer(rhs)) => Integer(lhs % rhs),
   270	            (Integer(lhs), Float(rhs)) => Float(*lhs as f64 % rhs),
   271	            (Float(lhs), Integer(rhs)) => Float(lhs % *rhs as f64),
   272	            (Float(lhs), Float(rhs)) => Float(lhs % rhs),
   273	            (Integer(_) | Float(_) | Null, Null) => Null,
   274	            (Null, Integer(_) | Float(_)) => Null,
   275	            (lhs, rhs) => return errinput!("can't take remainder of {lhs} and {rhs}"),
   276	        })
   277	    }
