   279	    /// Subtracts two values. Errors if invalid.
   280	    pub fn checked_sub(&self, other: &Self) -> Result<Self> {
   281	        use Value::*;
   282	
   283	        Ok(match (self, other) {
   284	            (Integer(lhs), Integer(rhs)) => match lhs.checked_sub(*rhs) {
   285	                Some(i) => Integer(i),
   286	                None => return errinput!("integer overflow"),
   287	            },
   288	            (Integer(lhs), Float(rhs)) => Float(*lhs as f64 - rhs),
   289	            (Float(lhs), Integer(rhs)) => Float(lhs - *rhs as f64),
   290	            (Float(lhs), Float(rhs)) => Float(lhs - rhs),
   291	            (Null, Integer(_) | Float(_) | Null) => Null,
   292	            (Integer(_) | Float(_), Null) => Null,
   293	            (lhs, rhs) => return errinput!("can't subtract {lhs} and {rhs}"),
   294	        })
   295	    }
