   146	        fn run(&mut self, command: &goldenscript::Command) -> Result<String, Box<dyn Error>> {
   147	            let mut output = String::new();
   148	
   149	            // Obtain a session based on the command prefix ("" if none).
   150	            let prefix = command.prefix.clone().unwrap_or_default();
   151	            let session = self.sessions.entry(prefix).or_insert_with(|| self.engine.session());
   152	
   153	            // Handle runner commands.
   154	            match command.name.as_str() {
   155	                // dump
   156	                "dump" => {
   157	                    command.consume_args().reject_rest()?;
   158	                    let mut engine = self.engine.mvcc.engine.lock().expect("mutex failed");
   159	                    let mut iter = engine.scan(..);
   160	                    while let Some((key, value)) = iter.next().transpose()? {
   161	                        let fmtkv = format::MVCC::<format::SQL>::key_value(&key, &value);
   162	                        let rawkv = format::Raw::key_value(&key, &value);
   163	                        writeln!(output, "{fmtkv} [{rawkv}]",)?;
   164	                    }
   165	                    return Ok(output);
   166	                }
   167	
   168	                // schema [TABLE...]
   169	                "schema" => {
   170	                    let mut args = command.consume_args();
   171	                    let tables = args.rest_pos().iter().map(|arg| arg.value.clone()).collect_vec();
   172	                    args.reject_rest()?;
   173	
   174	                    let schemas = if tables.is_empty() {
   175	                        session.with_txn(true, |txn| txn.list_tables())?
   176	                    } else {
   177	                        tables
   178	                            .into_iter()
   179	                            .map(|t| session.with_txn(true, |txn| txn.must_get_table(&t)))
   180	                            .try_collect()?
   181	                    };
   182	                    return Ok(schemas.into_iter().join("\n"));
   183	                }
   184	
   185	                // Otherwise, fall through to SQL execution.
   186	                _ => {}
   187	            }
   188	
   189	            // The entire command is the SQL statement. There are no args.
   190	            if !command.args.is_empty() {
   191	                return Err("SQL statements should be given as a command with no args".into());
   192	            }
   193	            let input = &command.name;
   194	            let mut tags = command.tags.clone();
   195	
   196	            // Output the plan if requested.
   197	            if tags.remove("plan") {
   198	                let ast = Parser::parse(input)?;
   199	                let plan =
   200	                    session.with_txn(true, |txn| Planner::new(txn).build(ast)?.optimize())?;
   201	                writeln!(output, "{plan}")?;
   202	            }
   203	
   204	            // Output plan optimizations if requested.
   205	            if tags.remove("opt") {
   206	                if tags.contains("plan") {
   207	                    return Err("using both plan and opt is redundant".into());
   208	                }
   209	                let ast = Parser::parse(input)?;
   210	                let plan = session.with_txn(true, |txn| Planner::new(txn).build(ast))?;
   211	                let Plan::Select(mut root) = plan else {
   212	                    return Err("can only use opt with SELECT plans".into());
   213	                };
   214	                writeln!(output, "{}", format!("Initial:\n{root}").replace('\n', "\n   "))?;
   215	                for optimizer in OPTIMIZERS.iter() {
   216	                    let prev = root.clone();
   217	                    root = optimizer.optimize(root)?;
   218	                    if root != prev {
   219	                        writeln!(
   220	                            output,
   221	                            "{}",
   222	                            format!("{optimizer:?}:\n{root}").replace('\n', "\n   ")
   223	                        )?;
   224	                    }
   225	                }
   226	            }
   227	
   228	            // Execute the statement.
   229	            let result = session.execute(input)?;
   230	
   231	            // Output engine ops if requested.
   232	            if tags.remove("ops") {
   233	                while let Ok(op) = self.op_rx.try_recv() {
   234	                    match op {
   235	                        testengine::Operation::Delete { key } => {
   236	                            let fmtkey = format::MVCC::<format::SQL>::key(&key);
   237	                            let rawkey = format::Raw::key(&key);
   238	                            writeln!(output, "delete {fmtkey} [{rawkey}]")?;
   239	                        }
   240	                        testengine::Operation::Flush => writeln!(output, "flush")?,
   241	                        testengine::Operation::Set { key, value } => {
   242	                            let fmtkv = format::MVCC::<format::SQL>::key_value(&key, &value);
   243	                            let rawkv = format::Raw::key_value(&key, &value);
   244	                            writeln!(output, "set {fmtkv} [{rawkv}]")?;
   245	                        }
   246	                    }
   247	                }
   248	            }
   249	
   250	            // Output the result if requested. SELECT results are always output.
   251	            match result {
   252	                StatementResult::Select { columns, rows } => {
   253	                    if tags.remove("header") {
   254	                        writeln!(output, "{}", columns.into_iter().join(", "))?;
   255	                    }
   256	                    for row in rows {
   257	                        writeln!(output, "{}", row.into_iter().join(", "))?;
