    /// Creates a new planner.
    pub fn new(catalog: &'a C) -> Self {
        Planner { catalog }
    }

    /// Builds a plan for an AST statement.
    pub fn build(&mut self, statement: ast::Statement) -> Result<Plan> {
        match statement {
            ast::Statement::Begin { .. } => Ok(Plan::Begin),
            ast::Statement::Commit => Ok(Plan::Commit),
            ast::Statement::Rollback => Ok(Plan::Rollback),
            ast::Statement::Explain(stmt) => {
                let plan = self.build(*stmt)?;
                Ok(Plan::Explain(Box::new(plan)))
            }
            ast::Statement::CreateTable { name, columns } => self.build_create_table(name, columns),
            ast::Statement::DropTable { name, if_exists } => self.build_drop_table(name, if_exists),
            ast::Statement::Delete { table, r#where } => self.build_delete(table, r#where),
            ast::Statement::Insert { table, columns, values } => self.build_insert(table, columns, values),
            ast::Statement::Update { table, set, r#where } => self.build_update(table, set, r#where),
            ast::Statement::Select { select, from, r#where, group_by, having, order_by, offset, limit } => {
                self.build_select(select, from, r#where, group_by, having, order_by, offset, limit)
            }
        }
    }

    /// Builds a CREATE TABLE plan.
    fn build_create_table(&self, name: String, columns: Vec<ast::Column>) -> Result<Plan> {
        let mut table_columns = Vec::new();
        for col in columns {
            table_columns.push(Column {
                name: col.name,
                datatype: col.datatype,
                primary_key: col.primary_key,
                nullable: col.nullable.unwrap_or(true),
                default: col.default,
                unique: col.unique,
                index: col.index,
                references: col.references,
            });
        }
        let table = Table {
            name,
            columns: table_columns,
        };
        Ok(Plan::CreateTable(table))
    }

    /// Builds a DROP TABLE plan.
    fn build_drop_table(&self, name: String, if_exists: bool) -> Result<Plan> {
        Ok(Plan::DropTable { name, if_exists })
    }

    /// Builds a DELETE plan.
    fn build_delete(&self, table: String, r#where: Option<ast::Expression>) -> Result<Plan> {
        Ok(Plan::Delete { table, r#where })
    }

    /// Builds an INSERT plan.
    fn build_insert(
        &self,
        table: String,
        columns: Option<Vec<String>>,
        values: Vec<Vec<ast::Expression>>,
    ) -> Result<Plan> {
        Ok(Plan::Insert { table, columns, values })
    }

    /// Builds an UPDATE plan.
    fn build_update(
        &self,
        table: String,
        set: BTreeMap<String, Option<ast::Expression>>,
        r#where: Option<ast::Expression>,
    ) -> Result<Plan> {
        Ok(Plan::Update { table, set, r#where })
    }

    /// Builds a SELECT plan.
    #[allow(clippy::too_many_arguments)]
    fn build_select(
        &self,
        mut select: Vec<(ast::Expression, Option<String>)>,
        from: Vec<ast::From>,
        r#where: Option<ast::Expression>,
        group_by: Vec<ast::Expression>,
        having: Option<ast::Expression>,
        order_by: Vec<(ast::Expression, ast::Direction)>,
        offset: Option<ast::Expression>,
        limit: Option<ast::Expression>,
    ) -> Result<Plan> {
        // If no FROM clause, check if we have constant expressions
        if from.is_empty() {
            // For constant selects, we need a VALUES node
            // Check if all expressions are constant (no column references)
            let mut has_columns = false;
            for (expr, _) in &select {
                if expr.contains(&|e| matches!(e, ast::Expression::Column(_, _))) {
                    has_columns = true;
                    break;
                }
            }

            if !has_columns {
                // Constant select - create a VALUES node with a blank row
                let mut scope = Scope::new();
                let mut expressions = Vec::new();
                for (expr, alias) in &select {
                    let built_expr = self.build_expression(expr.clone(), &scope)?;
                    expressions.push((built_expr, alias.clone()));
                }
                return Ok(Plan::Select {
                    select: expressions,
                    from: vec![],
                    r#where: None,
                    group_by: vec![],
                    having: None,
                    order_by: vec![],
                    offset: None,
                    limit: None,
                });
            }
        }

        // Build FROM clause
        let mut scope = Scope::new();
        let from_node = if from.is_empty() {
            // No FROM clause with columns - error
            return errinput!("SELECT requires a FROM clause when selecting columns");
        } else {
            self.build_from_clause(from, &mut scope)?
        };

        // Build WHERE clause
        let where_expr = if let Some(expr) = r#where {
            Some(self.build_expression(expr, &scope)?)
        } else {
            None
        };

        // Collect aggregates before building GROUP BY
        let aggregates = self.collect_aggregates(&select, &having, &order_by);

        // Build GROUP BY and aggregate
        let mut node = from_node;
        let mut aggregate_scope = scope.spawn();

        if !group_by.is_empty() || !aggregates.is_empty() {
            // Build GROUP BY expressions
            let mut group_by_exprs = Vec::new();
            for expr in &group_by {
                group_by_exprs.push(self.build_expression(expr.clone(), &scope)?);
            }

            // Build aggregate expressions
            let mut agg_exprs = Vec::new();
            for expr in &aggregates {
                agg_exprs.push(self.build_expression(expr.clone(), &scope)?);
            }

            node = self.build_aggregate(node, group_by_exprs, agg_exprs, &mut aggregate_scope)?;
        }

        // Build SELECT expressions
        let mut select_exprs = Vec::new();
        for (expr, alias) in &select {
            select_exprs.push((self.build_expression(expr.clone(), &aggregate_scope)?, alias.clone()));
        }

        // Build HAVING clause
        let having_expr = if let Some(expr) = having {
            Some(self.build_expression(expr, &aggregate_scope)?)
        } else {
            None
        };

        // Build ORDER BY expressions
        let mut order_by_exprs = Vec::new();
        for (expr, dir) in &order_by {
            order_by_exprs.push((self.build_expression(expr.clone(), &aggregate_scope)?, dir.clone()));
        }

        // Build OFFSET and LIMIT
        let offset_expr = if let Some(expr) = offset {
            Some(self.build_expression(expr, &aggregate_scope)?)
        } else {
            None
        };

        let limit_expr = if let Some(expr) = limit {
            Some(self.build_expression(expr, &aggregate_scope)?)
        } else {
            None
        };

        Ok(Plan::Select {
            select: select_exprs,
            from: vec![Node::Select {
                source: Box::new(node),
                select: select_exprs.clone(),
                r#where: where_expr.clone(),
                group_by: vec![],
                having: None,
                order_by: vec![],
                offset: None,
                limit: None,
            }],
            r#where: where_expr,
            group_by: vec![],
            having: having_expr,
            order_by: order_by_exprs,
            offset: offset_expr,
            limit: limit_expr,
        })
    }

    /// Builds a FROM clause consisting of one or more items.
    fn build_from_clause(&self, from: Vec<ast::From>, scope: &mut Scope) -> Result<Node> {
        let mut node = self.build_from(from[0].clone(), scope)?;

        for from_item in from.into_iter().skip(1) {
            let join_node = self.build_from(from_item, scope)?;
            // For now, just chain them - the optimizer will handle joins
            node = Node::Join {
                left: Box::new(node),
                right: Box::new(join_node),
                r#type: ast::JoinType::Inner,
                predicate: None,
            };
        }

        Ok(node)
    }

    /// Builds FROM items, which can either be a single table or a chained join
    /// of multiple tables.
    fn build_from(&self, from: ast::From, parent_scope: &mut Scope) -> Result<Node> {
        match from {
            ast::From::Table { name, alias } => {
                let table = self.catalog.must_get_table(&name)?;
                let table_name = alias.unwrap_or_else(|| name.clone());

                let mut scope = Scope::from_table(&table)?;
                scope.add_table(&table, Some(&table_name))?;

                // Merge with parent scope
                parent_scope.merge(scope)?;

                Ok(Node::Scan {
                    table: name,
                    alias: alias,
                    filter: None,
                })
            }
            ast::From::Join { left, right, r#type, predicate } => {
                let left_node = self.build_from(*left, parent_scope)?;
                let right_node = self.build_from(*right, parent_scope)?;

                Ok(Node::Join {
                    left: Box::new(left_node),
                    right: Box::new(right_node),
                    r#type,
                    predicate: predicate.map(|e| self.build_expression(e, parent_scope)).transpose()?,
                })
            }
        }
    }

    /// Builds an aggregate node.
    fn build_aggregate(
        &self,
        source: Node,
        mut group_by: Vec<ast::Expression>,
        mut aggregates: Vec<ast::Expression>,
        scope: &mut Scope,
    ) -> Result<Node> {
        // Build aggregate functions
        let mut agg_functions = Vec::new();
        for expr in &aggregates {
            agg_functions.push(self.build_aggregate_function(expr.clone(), scope)?);
        }

        Ok(Node::Aggregate {
            source: Box::new(source),
            group_by,
            aggregates: agg_functions,
        })
    }

    /// Builds an aggregate function from an AST expression.
    fn build_aggregate_function(expr: ast::Expression, scope: &Scope) -> Result<Aggregate> {
        let ast::Expression::Function(name, args) = expr else {
            return errinput!("expected aggregate function");
        };

        let args = args.into_iter()
            .map(|arg| {
                // For aggregate arguments, we need to evaluate them in the parent scope
                // For now, just return a simple expression
                Ok(Expression::Column(None, String::new()))
            })
            .collect::<Result<Vec<_>>>()?;

        Ok(Aggregate {
            name,
            args,
        })
    }

    /// Checks whether a given AST expression is an aggregate function.
    fn is_aggregate_function(expr: &ast::Expression) -> bool {
        matches!(expr, ast::Expression::Function(name, _) if matches!(name.as_str(), 
            "count" | "sum" | "avg" | "min" | "max" | "median" | "string_agg"
        ))
    }

    /// Collects aggregate functions from SELECT, HAVING, and ORDER BY clauses.
    fn collect_aggregates(
        select: &[(ast::Expression, Option<String>)],
        having: &Option<ast::Expression>,
        order_by: &[(ast::Expression, ast::Direction)],
    ) -> Vec<ast::Expression> {
        let mut aggregates = Vec::new();

        for (expr, _) in select {
            expr.collect(&|e| Self::is_aggregate_function(e), &mut aggregates);
        }

        if let Some(expr) = having {
            expr.collect(&|e| Self::is_aggregate_function(e), &mut aggregates);
        }

        for (expr, _) in order_by {
            expr.collect(&|e| Self::is_aggregate_function(e), &mut aggregates);
        }

        aggregates
    }

    /// Builds hidden columns for a projection to pass through columns that are
    /// used by downstream nodes.
    fn build_select_hidden(
        &self,
        having: &Option<ast::Expression>,
        order_by: &[(ast::Expression, ast::Direction)],
        scope: &Scope,
        child_scope: &mut Scope,
    ) -> Vec<Expression> {
        let mut hidden = Vec::new();

        // For now, return empty - this is a simplification
        hidden
    }

    /// Builds an expression from an AST expression, looking up columns and
    /// aggregate expressions in the scope.
    pub fn build_expression(expr: ast::Expression, scope: &Scope) -> Result<Expression> {
        match expr {
            ast::Expression::All => errinput!("unsupported use of *"),
            ast::Expression::Column(table, name) => {
                let index = scope.lookup_column(table.as_deref(), &name)?;
                Ok(Expression::Column(index))
            }
            ast::Expression::Literal(lit) => {
                let value = match lit {
                    ast::Literal::Null => Value::Null,
                    ast::Literal::Boolean(b) => Value::Boolean(b),
                    ast::Literal::Integer(i) => Value::Integer(i),
                    ast::Literal::Float(f) => Value::Float(f),
                    ast::Literal::String(s) => Value::String(s),
                };
                Ok(Expression::Value(value))
            }
            ast::Expression::Function(name, args) => {
                let args = args.into_iter()
                    .map(|arg| Self::build_expression(arg, scope))
                    .collect::<Result<Vec<_>>>()?;
